'use client'

import React, { useState, useCallback, useRef, useEffect } from 'react';
import PlinkoGame from '../components/PlinkoGame';
import MainNav from '../components/MainNav';
import AutoPlayModal from '../components/AutoPlayModal';
import PresetAmountsModal from '../components/PresetAmountsModal';
import ExtendedHistoryModal from '../components/ExtendedHistoryModal';
import { GameState, RiskLevel } from '../types';
import { COLORS } from '../constants';

interface AutoPlaySettings {
  riskLevel: RiskLevel;
  numberOfRounds: number;
  stopOnLossEnabled: boolean;
  stopOnLossAmount: number;
  stopOnBigWinEnabled: boolean;
  stopOnBigWinAmount: number;
  stopOnProfitEnabled: boolean;
  stopOnProfitAmount: number;
  onLossStrategy: 'reset' | 'increase' | 'decrease';
  onLossPercent: number;
  onWinStrategy: 'reset' | 'increase' | 'decrease';
  onWinPercent: number;
}

interface HistoryItem {
  id: number;
  multiplier: number;
  risk: RiskLevel;
}

const Home: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    balance: 755.37,
    ballCount: 0
  });

  const [wager, setWager] = useState(0.30);
  const [dropTrigger, setDropTrigger] = useState(0);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isAutoDrop, setIsAutoDrop] = useState(false);
  const [showAutoPlayModal, setShowAutoPlayModal] = useState(false);
  const [showPresetModal, setShowPresetModal] = useState(false);
  const [showExtendedHistory, setShowExtendedHistory] = useState(false);
  const [autoPlaySettings, setAutoPlaySettings] = useState<AutoPlaySettings | null>(null);
  const [remainingBalls, setRemainingBalls] = useState(0);
  const [isMobile, setIsMobile] = useState(false);
  const [profitLossBadge, setProfitLossBadge] = useState<{ amount: number; show: boolean } | null>(null);
  const lastRiskRef = useRef<RiskLevel>('GREEN');
  const lastDropTime = useRef<number>(0);
  const historyIdCounter = useRef(0);

  // AutoPlay state tracking
  const initialWagerRef = useRef(0.30);
  const startingBalanceRef = useRef(755.37);
  const lastWinAmountRef = useRef(0);


  const handleScore = useCallback((multiplier: number) => {
    const winAmount = wager * multiplier;
    const profit = winAmount - wager;
    lastWinAmountRef.current = winAmount;

    // Show profit/loss badge
    setProfitLossBadge({ amount: profit, show: true });
    setTimeout(() => {
      setProfitLossBadge(prev => prev ? { ...prev, show: false } : null);
    }, 2000);

    setGameState(prev => {
      const newBalance = prev.balance + winAmount;

      // Check AutoPlay stop conditions
      if (isAutoDrop && autoPlaySettings) {
        // Stop if cash decreases by
        if (autoPlaySettings.stopOnLossEnabled) {
          const totalLoss = startingBalanceRef.current - newBalance;
          if (totalLoss >= autoPlaySettings.stopOnLossAmount) {
            setIsAutoDrop(false);
            setRemainingBalls(0);
          }
        }

        // Stop if single win exceeds
        if (autoPlaySettings.stopOnBigWinEnabled && winAmount >= autoPlaySettings.stopOnBigWinAmount) {
          setIsAutoDrop(false);
          setRemainingBalls(0);
        }

        // Stop if cash increases by
        if (autoPlaySettings.stopOnProfitEnabled) {
          const totalProfit = newBalance - startingBalanceRef.current;
          if (totalProfit >= autoPlaySettings.stopOnProfitAmount) {
            setIsAutoDrop(false);
            setRemainingBalls(0);
          }
        }

        // Apply bet progression strategy
        const isWin = multiplier > 1;
        const strategy = isWin ? autoPlaySettings.onWinStrategy : autoPlaySettings.onLossStrategy;
        const percent = isWin ? autoPlaySettings.onWinPercent : autoPlaySettings.onLossPercent;

        if (strategy === 'reset') {
          setWager(initialWagerRef.current);
        } else if (strategy === 'increase') {
          setWager(prev => +(prev * (1 + percent / 100)).toFixed(2));
        } else if (strategy === 'decrease') {
          setWager(prev => Math.max(0.1, +(prev * (1 - percent / 100)).toFixed(2)));
        }
      }

      return {
        ...prev,
        balance: newBalance
      };
    });

    // Generate unique ID using counter to prevent duplicate keys
    historyIdCounter.current += 1;
    const uniqueId = Date.now() * 1000 + historyIdCounter.current;

    setHistory(prev => [
      { id: uniqueId, multiplier, risk: lastRiskRef.current },
      ...prev
    ].slice(0, 15));
  }, [wager, isAutoDrop, autoPlaySettings]);

  const dropBall = useCallback((risk: RiskLevel) => {
    const now = Date.now();
    const timeSinceLastDrop = now - lastDropTime.current;

    // Prevent dropping balls too rapidly (200ms cooldown)
    if (timeSinceLastDrop < 200) {
      console.log('Drop too rapid, ignoring');
      return;
    }

    lastDropTime.current = now;
    console.log(`dropBall called with risk: ${risk}, time since last: ${timeSinceLastDrop}ms`);

    // Update risk immediately
    lastRiskRef.current = risk;

    // Check balance and update state
    setGameState(prevState => {
      // Check balance using current state to avoid stale closures
      if (prevState.balance < wager) {
        setIsAutoDrop(false);
        console.log('Insufficient balance, aborting drop');
        return prevState;
      }

      console.log(`Dropping ball, balance: ${prevState.balance} -> ${prevState.balance - wager}`);

      // Update game state with functional update
      return {
        ...prevState,
        balance: prevState.balance - wager,
        ballCount: prevState.ballCount + 1
      };
    });

    // Trigger ball drop AFTER state update (separate call to avoid double-triggering)
    setTimeout(() => {
      setDropTrigger(prev => {
        const newTrigger = prev + 1;
        console.log(`dropTrigger: ${prev} -> ${newTrigger}`);
        return newTrigger;
      });
    }, 0);
  }, [wager]);

  // AutoPlay handler
  const handleStartAutoPlay = useCallback((settings: AutoPlaySettings) => {
    setAutoPlaySettings(settings);
    setRemainingBalls(settings.numberOfRounds);
    initialWagerRef.current = wager;
    startingBalanceRef.current = gameState.balance;
    setIsAutoDrop(true);
  }, [wager, gameState.balance]);

  // Auto Drop Logic
  useEffect(() => {
    let interval: number | null = null;
    if (isAutoDrop && remainingBalls > 0 && autoPlaySettings) {
      interval = window.setInterval(() => {
        dropBall(autoPlaySettings.riskLevel);
        setRemainingBalls(prev => {
          const newCount = prev - 1;
          if (newCount <= 0) {
            setIsAutoDrop(false);
            setRemainingBalls(0);
          }
          return newCount;
        });
      }, 1000); // Fixed 1 second interval
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isAutoDrop, dropBall, remainingBalls, autoPlaySettings]);

  // Detect mobile devices for responsive background
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 440); // Mobile breakpoint at 640px
    };

    checkMobile(); // Check on mount
    window.addEventListener('resize', checkMobile);

    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const adjustWager = (amount: number) => {
    setWager(prev => Math.max(0.1, +(prev + amount).toFixed(2)));
  };


  return (
    <div
      className="flex flex-col min-h-screen w-full transition-all duration-1000 overflow-y-auto"
      style={{
        backgroundImage: `url("${isMobile ? '/ui/bg6.jpeg' : '/ui/pg.png'}")`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        backgroundAttachment: 'fixed',
        backgroundColor: 'black'
      }}
    >
      {/* Main Navigation */}
      <MainNav />

      {/* HEADER SECTION */}
      <header className="flex justify-between items-center px-2 py-1 z-30 bg-white/10 backdrop-blur-sm border-b border-white/20 mt-[45px]">
        {/* History (Left) */}
        <div className="flex items-center gap-1 max-w-[60%] overflow-hidden">
          <button
            onClick={() => setShowExtendedHistory(true)}
            className="w-8 h-8 rounded-full border-2 border-white/40 bg-white/10 hover:bg-white/20 text-white transition-all flex items-center justify-center flex-shrink-0"
            title="View extended history"
          >
            <i className="fas fa-history text-xs"></i>
          </button>
          <div className="flex gap-0.5 overflow-x-auto no-scrollbar scroll-smooth">
            {history.length > 0 ? history.map((item, index) => {
              // Determine color based on risk level and multiplier
              let bgColor = '';
              const isDark = item.multiplier < 1;

              if (item.risk === 'GREEN') {
                bgColor = isDark ? 'bg-[rgb(100,140,45)]' : 'bg-[rgb(140,185,60)]';
              } else if (item.risk === 'YELLOW') {
                bgColor = isDark ? 'bg-[rgb(180,115,30)]' : 'bg-[rgb(230,150,40)]';
              } else if (item.risk === 'RED') {
                bgColor = isDark ? 'bg-[rgb(160,35,35)]' : 'bg-[rgb(210,50,50)]';
              }

              return (
                <div
                  key={item.id}
                  className={`${bgColor} ${index === 0 ? 'history-item-enter' : ''} hover:brightness-110 px-1.5 py-0.5 rounded text-[8px] font-black min-w-fit border border-black/30 text-black shadow-md transition-all duration-300 hover:scale-105`}
                >
                  {item.multiplier}x
                </div>
              );
            }) : (
              <div className="text-[8px] text-white/60 font-bold uppercase tracking-widest px-1 italic">Waiting for results...</div>
            )}
          </div>
        </div>

        {/* Balance (Right) */}
        <div className="flex items-center gap-[1px]">
          {/* Profit/Loss Badge */}
          {profitLossBadge && profitLossBadge.amount !== 0 && (
            <div className={`${profitLossBadge.show ? 'profit-badge-enter' : 'profit-badge-exit'} ${profitLossBadge.amount > 0 ? 'bg-green-500' : 'bg-red-500'} px-1.5 py-0.5 rounded text-[8px] font-black text-white shadow-md border border-black/20`}>
              {profitLossBadge.amount > 0 ? '+' : ''}{profitLossBadge.amount.toFixed(2)}
            </div>
          )}

          {/* Balance Display */}
          <div className="flex items-center gap-1 bg-white/20 px-2 py-1 rounded-lg border border-white/30 shadow-inner hover:bg-white/25 transition-colors duration-200">
            <span className="text-white font-black text-[10px] tracking-tight">
              {gameState.balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </span>
            <span className="text-white/80 text-[7px] font-black">USD</span>
          </div>
        </div>
      </header>

      {/* MAIN CONTENT - Single column layout */}
      <main className="flex-1 flex flex-col gap-1 p-1 pb-1">
        {/* GAME BOARD */}
        <div className="w-full flex justify-center items-start bg-black/5 rounded-lg border border-black/10 shadow-inner pt-1">
          <PlinkoGame
            onScore={handleScore}
            dropTrigger={dropTrigger}
            currentRisk={lastRiskRef.current}
          />
        </div>

        {/* CONTROLS - Responsive Layout */}
        <div>
          {/* Desktop Layout - Single Row */}
          <div className="hidden lg:flex items-center justify-center gap-2 p-2">
            {/* Bet Amount Display */}
            <div className="bg-gradient-to-b from-gray-700 to-gray-800 rounded-full px-5 py-2 shadow-md border border-gray-600 min-w-[140px]">
              <div className="text-center">
                <div className="text-white/60 text-[9px] font-medium uppercase tracking-wide">Bet USD</div>
                <div className="text-white font-bold text-lg font-mono">{wager.toFixed(2)}</div>
              </div>
            </div>

            {/* Control Buttons Group */}
            <div className="flex items-center gap-1.5">
              <button
                onClick={() => adjustWager(-0.1)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white font-bold text-xl shadow-md active:scale-95 transition-all"
              >
                −
              </button>
              <button
                onClick={() => setShowPresetModal(true)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white shadow-md active:scale-95 transition-all flex items-center justify-center"
              >
                <i className="fas fa-layer-group text-sm"></i>
              </button>
              <button
                onClick={() => adjustWager(0.1)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white font-bold text-xl shadow-md active:scale-95 transition-all"
              >
                +
              </button>
            </div>

            {/* Auto Play Button */}
            <button
              onClick={() => {
                if (isAutoDrop) {
                  setIsAutoDrop(false);
                  setRemainingBalls(0);
                } else {
                  setShowAutoPlayModal(true);
                }
              }}
              className={`w-12 h-12 rounded-full shadow-lg active:scale-95 transition-all flex items-center justify-center ${
                isAutoDrop
                  ? 'bg-gradient-to-b from-orange-400 to-orange-500'
                  : 'bg-gradient-to-b from-blue-500 to-blue-600 hover:from-blue-400 hover:to-blue-500'
              }`}
            >
              {isAutoDrop ? (
                <span className="text-white font-bold text-sm">{remainingBalls}</span>
              ) : (
                <i className="fas fa-sync-alt text-white text-lg"></i>
              )}
            </button>

            {/* Risk Level Buttons - Height matched to auto button */}
            <button
              onClick={() => dropBall('GREEN')}
              className="h-12 px-6 rounded-full bg-gradient-to-b from-green-500 to-green-600 hover:from-green-400 hover:to-green-500 text-white font-bold text-sm shadow-lg active:scale-95 transition-all uppercase tracking-wider"
            >
              GREEN
            </button>
            <button
              onClick={() => dropBall('YELLOW')}
              className="h-12 px-6 rounded-full bg-gradient-to-b from-yellow-500 to-yellow-600 hover:from-yellow-400 hover:to-yellow-500 text-white font-bold text-sm shadow-lg active:scale-95 transition-all uppercase tracking-wider"
            >
              YELLOW
            </button>
            <button
              onClick={() => dropBall('RED')}
              className="h-12 px-6 rounded-full bg-gradient-to-b from-red-500 to-red-600 hover:from-red-400 hover:to-red-500 text-white font-bold text-sm shadow-lg active:scale-95 transition-all uppercase tracking-wider"
            >
              RED
            </button>
          </div>

          {/* Mobile Layout - 2 Rows */}
          <div className="lg:hidden flex flex-col gap-1 p-1">
            {/* Row 1: Auto + Risk Buttons */}
            <div className="flex items-center justify-center gap-2">
              <button
                onClick={() => {
                  if (isAutoDrop) {
                    setIsAutoDrop(false);
                    setRemainingBalls(0);
                  } else {
                    setShowAutoPlayModal(true);
                  }
                }}
                className={`w-12 h-12 rounded-full shadow-lg active:scale-95 transition-all flex items-center justify-center ${
                  isAutoDrop
                    ? 'bg-gradient-to-b from-orange-400 to-orange-500'
                    : 'bg-gradient-to-b from-blue-500 to-blue-600 hover:from-blue-400 hover:to-blue-500'
                }`}
              >
                {isAutoDrop ? (
                  <span className="text-white font-bold text-sm">{remainingBalls}</span>
                ) : (
                  <i className="fas fa-sync-alt text-white text-lg"></i>
                )}
              </button>

              <button
                onClick={() => dropBall('GREEN')}
                className="h-12 px-5 rounded-full bg-gradient-to-b from-green-500 to-green-600 hover:from-green-400 hover:to-green-500 text-white font-bold text-xs shadow-lg active:scale-95 transition-all uppercase"
              >
                GREEN
              </button>
              <button
                onClick={() => dropBall('YELLOW')}
                className="h-12 px-4 rounded-full bg-gradient-to-b from-yellow-500 to-yellow-600 hover:from-yellow-400 hover:to-yellow-500 text-white font-bold text-xs shadow-lg active:scale-95 transition-all uppercase"
              >
                YELLOW
              </button>
              <button
                onClick={() => dropBall('RED')}
                className="h-12 px-5 rounded-full bg-gradient-to-b from-red-500 to-red-600 hover:from-red-400 hover:to-red-500 text-white font-bold text-xs shadow-lg active:scale-95 transition-all uppercase"
              >
                RED
              </button>
            </div>

            {/* Row 2: Bet Display + Control Buttons */}
            <div className="flex items-center justify-center gap-2">
              <div className="bg-gradient-to-b from-gray-700 to-gray-800 rounded-full px-5 py-1.5 shadow-md border border-gray-600 flex-1 max-w-[180px]">
                <div className="text-center">
                  <div className="text-white/60 text-[8px] font-medium uppercase">Bet USD</div>
                  <div className="text-white font-bold text-base font-mono">{wager.toFixed(2)}</div>
                </div>
              </div>

              <button
                onClick={() => adjustWager(-0.1)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white font-bold text-lg shadow-md active:scale-95 transition-all"
              >
                −
              </button>
              <button
                onClick={() => setShowPresetModal(true)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white shadow-md active:scale-95 transition-all flex items-center justify-center"
              >
                <i className="fas fa-layer-group text-sm"></i>
              </button>
              <button
                onClick={() => adjustWager(0.1)}
                className="w-11 h-11 rounded-full bg-gradient-to-b from-gray-600 to-gray-700 hover:from-gray-500 hover:to-gray-600 text-white font-bold text-lg shadow-md active:scale-95 transition-all"
              >
                +
              </button>
            </div>
          </div>
        </div>
      </main>

      {/* AutoPlay Modal */}
      <AutoPlayModal
        open={showAutoPlayModal}
        onOpenChange={setShowAutoPlayModal}
        onStart={handleStartAutoPlay}
        currentBalance={gameState.balance}
      />

      {/* Preset Amounts Modal */}
      <PresetAmountsModal
        open={showPresetModal}
        onOpenChange={setShowPresetModal}
        onSelectAmount={setWager}
      />

      {/* Extended History Modal */}
      <ExtendedHistoryModal
        open={showExtendedHistory}
        onOpenChange={setShowExtendedHistory}
        history={history}
      />
    </div>
  );
};

export default Home;
